{
  "arguments": [
    {
      "claim": "The protection afforded to St Ilven Hospital under the Fourth Geneva Convention and Additional Protocol I ceased because the hospital was used to commit acts harmful to the enemy.",
      "reasoning": "Both GC IV art. 19 and API art. 13 provide that protection does not cease unless the medical unit is used to commit, outside its humanitarian function, acts harmful to the enemy. The facts show that Drennick forces used the hospital’s top floor as an artillery observation post, mounted a heavy machine gun on the roof that fired on Calvaran troops, and stored artillery ammunition in the basement. These activities constitute acts harmful to the enemy and are not among the exceptions listed in API art. 13(1)(a)‑(d), which only protect light individual weapons for self‑defence, pickets, small arms taken from the wounded, and the presence of combatants for medical reasons. Consequently, the hospital lost its protected status before the strike.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "gc_iv",
          "article": "19",
          "quoted_text": "The protection to which civilian hospitals are entitled shall not cease unless they are used to commit, outside their humanitarian duties, acts harmful to the enemy. Protection may, however, cease only after due warning has been given, naming, in all appropriate cases, a reasonable time limit, and after such warning has remained unheeded."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "13",
          "quoted_text": "The protection to which civilian medical units are entitled shall not cease unless they are used to commit, outside their humanitarian function, acts harmful to the enemy. Protection may, however, cease only after a warning has been given setting, whenever appropriate, a reasonable time-limit, and after such warning has remained unheeded."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "13(1)",
          "quoted_text": "that the personnel of the unit are equipped with light individual weapons for their own defence or for that of the wounded and sick in their charge; that the unit is guarded by a picket or by sentries or by an escort; that small arms and ammunition taken from the wounded and sick, and not yet handed to the proper service, are found in the units; that members of the armed forces or other combatants are in the unit for medical reasons."
        }
      ]
    },
    {
      "claim": "The termination of protection was lawful because Calvaran forces gave a due warning with a reasonable time‑limit that remained unheeded.",
      "reasoning": "GC IV art. 19 and API art. 13 require that protection may cease only after a warning has been given, specifying a reasonable time‑limit, and after that warning has been ignored. On 9 August Calvaran forces broadcast a warning, distributed leaflets, and delivered a notice through an ICRC delegate, demanding cessation of all military use of the hospital within 48 hours. The Drennick forces continued to use the roof machine gun on 10 and 11 August, thereby failing to heed the warning. The 48‑hour period elapsed, satisfying the statutory warning requirement, so the loss of protection was valid at the time of the 13 August strike.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "gc_iv",
          "article": "19",
          "quoted_text": "Protection may, however, cease only after due warning has been given, naming, in all appropriate cases, a reasonable time limit, and after such warning has remained unheeded."
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "13",
          "quoted_text": "Protection may, however, cease only after a warning has been given setting, whenever appropriate, a reasonable time-limit, and after such warning has remained unheeded."
        }
      ]
    },
    {
      "claim": "The 13 August air strike on the hospital’s top floor did not violate the prohibition on attacking medical units because the hospital had lost its protected status and the attack was directed at a legitimate military objective with no civilian presence, satisfying the principles of distinction and proportionality.",
      "reasoning": "Once protection ceased, the hospital premises became a lawful military target under international humanitarian law. API art. 12(4) expressly forbids using medical units to shield military objectives; the presence of the observation post and machine gun demonstrates that the hospital was being used as such a shield, justifying its targeting. The strike employed guided munitions aimed at the roof and top floor, where the combatants were located, and deliberately avoided the lower floors where civilians might have been present. At the time of the attack all patients and medical staff had evacuated, and only two Drennick soldiers were killed. No civilian harm occurred, satisfying the proportionality test. Therefore, the strike was consistent with the law of armed conflict and did not constitute a violation of the protection owed to civilian medical units.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "12",
          "quoted_text": "Under no circumstances shall medical units be used in an attempt to shield military objectives from attack."
        },
        {
          "type": "treaty",
          "instrument": "gc_iv",
          "article": "18",
          "quoted_text": "Civilian hospitals ... may in no circumstances be the object of attack, but shall at all times be respected and protected by the Parties to the conflict."
        }
      ]
    }
  ]
}
